import unittest
from orders.value import display_quantity
from orders.export import export_label

class Orders(unittest.TestCase):
    def test_display(self):
        self.assertEqual(display_quantity(2.0), "2")

    def test_label(self):
        self.assertEqual(export_label("order"), "order")

